#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> a(m);
    for (int i = 0; i < m; ++i) cin >> a[i];

    vector<string> ops;
    int nxt = 1;
    for (int x : a) {
        while (nxt <= x) {
            ops.push_back("In");
            if (nxt != x) ops.push_back("Out");
            ++nxt;
        }
        // x 留在栈上
    }
    for (int i = 0; i < (int)ops.size(); ++i) {
        if (i) cout << ",";
        cout << ops[i];
    }
    cout << "\n";
    return 0;
}
